DROP TABLE IF EXISTS `payment_reversals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_reversals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `original_payment_id` bigint unsigned NOT NULL,
  `reversal_amount` decimal(10,2) NOT NULL,
  `reversal_date` date NOT NULL,
  `reversed_by` bigint unsigned NOT NULL,
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `refund_method` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `payment_reversals_original_payment_id_foreign` (`original_payment_id`),
  CONSTRAINT `payment_reversals_original_payment_id_foreign` FOREIGN KEY (`original_payment_id`) REFERENCES `payments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
